const STORAGE_KEY = 'elk.language'; // Reuses the existing Settings key.
function readPreference(): Language {
  if (typeof window === 'undefined') return 'id';
  try {
    const value = window.localStorage.getItem(STORAGE_KEY);
    if(value === 'English' || value === 'en') return 'en';
    if(value === 'Bahasa Indonesia' || value === 'id') return 'id';
  } catch { /* Storage is optional. */ }
  return 'id';
}
let active: Language = 'id';
export function t(source:string):string { return translate(source); }

