export function translate(source: string): string {
  if(active === 'en') return idSources.has(source) ? (languagePairs[source] ?? source) : source;
  if(!idSources.has(source)) return languagePairs[source] ?? source;
  return source;
}
const LocaleContext = createContext<{language:Language;setLanguage:(value:Language)=>void}>({language:'id',setLanguage:()=>undefined});
export function LanguageProvider({children}:{children:ReactNode}) {
  const [language,update] = useState<Language>(()=>{active=readPreference();return active});
  const setLanguage = useCallback((value:Language)=>{
    active=value;
    try { window.localStorage.setItem(STORAGE_KEY, value==='en'?'English':'Bahasa Indonesia'); } catch { /* no-op */ }
    update(value);
  }, []);
  useEffect(()=>{document.documentElement.lang=language;},[language]);
  return <LocaleContext.Provider value={{language,setLanguage}}>{children}</LocaleContext.Provider>;
}
export function useLanguage(){return useContext(LocaleContext)}
export function LanguageSwitch(){
  const {language,setLanguage}=useLanguage();
  return <div className="elk-language-switch" role="group" aria-label="Bahasa / Language">
    <button type="button" className={language==='id'?'active':''} aria-pressed={language==='id'} onClick={()=>setLanguage('id')} lang="id" title="Bahasa Indonesia">ID</button>
    <button type="button" className={language==='en'?'active':''} aria-pressed={language==='en'} onClick={()=>setLanguage('en')} lang="en" title="English">EN</button>
  </div>
}
